4. What is the output?
public class ScopeTest {
    static int count = 0;
    int id;
    public ScopeTest() {
        count++;
        id = count;
    }
    public static void main(String[] args) {
        ScopeTest a = new ScopeTest();
        ScopeTest b = new ScopeTest();
        ScopeTest c = new ScopeTest();
        System.out.println(a.id + " " + b.id + " " + c.id);
        System.out.println(ScopeTest.count);
    }
}

